\encoding UTF8
\copy (SELECT json_build_object('id', q.id, 'subject', q.subject_area, 'q', q.question_text, 'a', q.option_a, 'b', q.option_b, 'c', q.option_c, 'd', q.option_d, 'e', q.option_e, 'key', q.correct_answer) FROM question_bank q WHERE q.id IN (SELECT id FROM v_safe_for_beta) AND q.pipeline_metadata::jsonb->>'student_coherent'='true' AND q.correct_answer IN ('A','B','C','D','E') AND q.option_a IS NOT NULL AND q.option_b IS NOT NULL AND q.option_c IS NOT NULL AND q.option_d IS NOT NULL AND q.option_e IS NOT NULL AND q.word_count >= 5 AND (length(q.question_text)-length(replace(q.question_text,'$','')))%2 = 0 ORDER BY md5(q.id)) TO 'C:/Users/husey/kiro2/backend/scripts/quality/_gate2b/master.csv' CSV
